"""V2 COPY of adjudication_compare.py: reads data/training/pairs_v2.csv (corrected labels) and writes only to results_v2/. Generated by make_v2_scripts.py; do not edit."""
"""Head-to-head on the ambiguous band: Gemini adjudicator vs fine-tuned cross-encoder vs Stage 2 alone.

Usage:  python adjudication_compare.py [zero] [few] [extra]     (default: all three, in that order)
Real rows only (label != -1), folds from folds.json, no synthetic data. Inputs are never modified.

Band = Stage 2 score in [0.45, 0.65). Outside the band the Stage 2 decision is kept
(>= 0.65 retake, < 0.45 not retake). Every Gemini response is cached in results/gemini_cache.jsonl,
keyed by (pair_id, variant), so reruns cost nothing. The prompt is fixed; changing it must use a new
variant name. The API key is read from GEMINI_API_KEY (env or the repo's .env) and never printed.
"""
from report_header import insert_header, labels_header  # run header for the report (captions only)
import json
import os
import sys
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

import numpy as np
import pandas as pd
import requests
from sklearn.metrics import precision_recall_curve

HERE = Path(__file__).resolve().parent
REPO = HERE.parents[1]
sys.path.insert(0, str(REPO))
OUT = HERE / "results_v2"
CACHE = OUT / "gemini_cache.jsonl"
FEWSHOT = OUT / "fewshot_examples.json"
LO, HI, S2_T = 0.45, 0.65, 0.65
N_BOOT, SEED, MAX_ATTEMPTS = 1000, 0, 6
WORKERS = int(os.environ.get("LLM_WORKERS", "14"))      # parallel requests (still limited by MIN_INTERVAL)
SUFFIX = os.environ.get("OUT_SUFFIX", "")          # optional: write adjudication<SUFFIX>.* instead of overwriting the earlier report
MIN_INTERVAL = 60.0 / float(os.environ.get("GEMINI_RPM", "14"))               # free tier allows 15 requests/minute; stay just under it
PRICE_IN, PRICE_OUT = 0.30, 2.50      # USD per 1M tokens, gemini-2.5-flash standard paid tier (docs checked)
MODEL_TAG = None                       # set below from the model name so different models never share cache entries
ZERO, FEW = None, None                 # prompt variants "<zero|few>_v1@<model>"; new prompt text => new version

# ---------------- API key (never printed) ----------------
import os                                                                          # noqa: E402
if not (os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY")):
    envf = REPO / ".env"
    if envf.exists():
        for line in envf.read_text().splitlines():
            if line.strip().startswith("GEMINI_API_KEY="):
                os.environ["GEMINI_API_KEY"] = line.split("=", 1)[1].strip().strip('"').strip("'")
BACKEND = os.environ.get("LLM_BACKEND", "gemini")          # "gemini" or "ollama" (local, free)
KEY = os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY") or ""
if BACKEND == "gemini" and not KEY:
    raise SystemExit("GEMINI_API_KEY is missing; stopping.")
from pipeline.step_06_llm_adjudication.config import ADJUDICATION_MODEL                   # noqa: E402
from pipeline.step_06_llm_adjudication.llm_client import GeminiClient                     # noqa: E402


def scrub(msg):
    """Make sure the key can never leak into logs or error messages."""
    return str(msg).replace(KEY, "<key>") if KEY else str(msg)


class MeteredGemini(GeminiClient):
    """Existing GeminiClient request/response handling, plus token usage for cost reporting."""
    def generate_json_usage(self, prompt):
        url = (f"https://generativelanguage.googleapis.com/v1beta/models/{self.model}:generateContent?key={self.api_key}")
        payload = {"contents": [{"parts": [{"text": prompt}]}],
                   "generationConfig": {"temperature": self.temperature, "responseMimeType": "application/json"}}
        r = requests.post(url, headers={"Content-Type": "application/json"}, json=payload, timeout=self.timeout_seconds)
        if r.status_code != 200:
            raise RuntimeError(f"status {r.status_code}: {r.text[:1500]}")
        data = r.json()
        if not data.get("candidates"):
            raise RuntimeError(f"no candidates: {str(data)[:300]}")
        text = data["candidates"][0].get("content", {}).get("parts", [{}])[0].get("text", "").strip()
        u = data.get("usageMetadata", {})
        return json.loads(text), {"in": u.get("promptTokenCount", 0),
                                  "out": u.get("candidatesTokenCount", 0) + u.get("thoughtsTokenCount", 0)}


ADJUDICATION_MODEL = os.environ.get("ADJUDICATION_MODEL", ADJUDICATION_MODEL)
ZERO, FEW = f"zero_v1@{ADJUDICATION_MODEL}", f"few_v1@{ADJUDICATION_MODEL}"
class OllamaClient:
    """Local Ollama chat client (JSON mode, temperature 0, fixed seed). Same generate_json_usage interface."""
    def __init__(self, model):
        self.model = model

    def generate_json_usage(self, prompt):
        r = requests.post("http://localhost:11434/api/chat", timeout=300, json={
            "model": self.model, "stream": False, "format": "json",
            "messages": [{"role": "user", "content": prompt}],
            "options": {"temperature": 0, "seed": 0}})
        if r.status_code != 200:
            raise RuntimeError(f"status {r.status_code}: {r.text[:1500]}")
        d = r.json()
        return json.loads(d["message"]["content"]), {"in": d.get("prompt_eval_count", 0), "out": d.get("eval_count", 0)}


if BACKEND == "ollama":
    ADJUDICATION_MODEL = os.environ.get("LLM_MODEL", "llama3:latest")
    ZERO, FEW = f"zero_v1@{ADJUDICATION_MODEL}", f"few_v1@{ADJUDICATION_MODEL}"
    PRICE_IN = PRICE_OUT = 0.0
    MIN_INTERVAL, WORKERS = 0.0, 2
    client = OllamaClient(ADJUDICATION_MODEL)
else:
  client = MeteredGemini(model=ADJUDICATION_MODEL, api_key=KEY, temperature=0.0, timeout_seconds=90.0)

# ---------------- data ----------------
df = pd.read_csv(HERE / "pairs_v2.csv", dtype=str, keep_default_na=False)
folds = json.loads((HERE / "folds.json").read_text())["folds"]
df = df[(df.is_synthetic == "0") & (df.label != "-1")].copy()
df["label"] = df.label.astype(int)
df["fold"] = df.video_id.map(folds).astype(int)
for c in ["lexical_score", "containment", "start_a", "start_b"]:
    df[c] = pd.to_numeric(df[c])
assert (df.start_a <= df.start_b).all(), "earlier unit must be text_a"
base = pd.read_csv(OUT / "baseline_scores.csv", dtype={"pair_id": str, "video_id": str})
ce = pd.read_csv(OUT / "ce_scores.csv", dtype={"pair_id": str}).drop_duplicates("pair_id")
df = df.merge(base[["pair_id", "current_stage2"]], on="pair_id", validate="1:1") \
       .merge(ce[["pair_id", "prob_mean"]].rename(columns={"prob_mean": "ce_prob"}), on="pair_id", validate="1:1")
df = df.reset_index(drop=True)
assert len(df) == len(base)
df["in_band"] = (df.current_stage2 >= LO) & (df.current_stage2 < HI)
df["s2_pred"] = (df.current_stage2 >= S2_T).astype(int)
errors = df[df.s2_pred != df.label]                      # the Stage 2 errors (count computed from the data)
print(f"band pairs {int(df.in_band.sum())} (positives {int(df[df.in_band].label.sum())}); Stage 2 errors {len(errors)}")

# ---------------- few-shot examples, fixed per held-out fold BEFORE scoring ----------------
def build_fewshot():
    """4 examples per held-out fold k, drawn only from band pairs of the other folds (seed 0):
    1 low-overlap retake, 1 other retake, 1 repeated-structure (high-overlap) non-retake, 1 other non-retake."""
    rng = np.random.default_rng(SEED)
    out = {}
    for k in sorted(df.fold.unique()):
        pool = df[(df.fold != k) & df.in_band].sample(frac=1, random_state=int(rng.integers(1 << 30)))
        pick = lambda m: pool[m].drop_duplicates(["text_a", "text_b"]).iloc[0]
        # low-overlap retake: lowest-lexical positive; other retake: a random remaining positive
        pos = pool[pool.label == 1].drop_duplicates(["text_a", "text_b"])
        r1 = pos[pos.lexical_score < 0.5].iloc[0] if (pos.lexical_score < 0.5).any() else pos.iloc[0]
        r2 = pos[pos.pair_id != r1.pair_id].iloc[0]
        # repeated-structure non-retake: the negative with the highest lexical overlap (band has none >= 0.65)
        neg = pool[pool.label == 0].drop_duplicates(["text_a", "text_b"])
        n1 = neg.sort_values(["lexical_score", "containment"], ascending=False).iloc[0]
        n2 = neg[neg.pair_id != n1.pair_id].iloc[0]
        out[str(k)] = [{"pair_id": r.pair_id, "video_id": r.video_id, "fold": int(r.fold), "label": int(r.label),
                        "text_a": r.text_a, "text_b": r.text_b, "role": role}
                       for r, role in [(r1, "low_overlap_retake"), (n1, "repeated_structure_non_retake"),
                                       (r2, "retake"), (n2, "non_retake")]]
    return out


if not FEWSHOT.exists():
    FEWSHOT.write_text(json.dumps(build_fewshot(), indent=2))
fewshot = json.loads(FEWSHOT.read_text())

# ---------------- prompts (fixed; do not edit after scoring) ----------------
HEAD = """You are an expert video editing and speech transcript adjudication assistant.
Two spoken units from a recording are shown in chronological order (Unit A spoke first, Unit B later).
Decide whether Unit B is a retake of Unit A: the speaker restarting, stumbling, revising, or repeating the SAME intended sentence/thought, where only the best version should remain in the final video.
It is NOT a retake if the units are distinct thoughts, deliberate topical repetition, a rhetorical callback, or parallel sentence structure that carries different content.
"""
TAIL = """
Return ONLY a valid JSON object:
{"same_intended_line": true | false, "confidence": "high" | "medium" | "low", "reasoning": "<one short sentence>"}
"""


def pair_block(a, b):
    return f'Unit A: "{a}"\nUnit B: "{b}"'


def make_prompt(row, variant):
    if variant == ZERO:
        return HEAD + "\n" + pair_block(row.text_a, row.text_b) + "\n" + TAIL
    ex = fewshot[str(row.fold)]
    shots = "\n\n".join(pair_block(e["text_a"], e["text_b"]) + "\nAnswer: "
                        + json.dumps({"same_intended_line": bool(e["label"])}) for e in ex)
    return (HEAD + "\nExamples:\n\n" + shots + "\n\nNow decide this pair.\n\n"
            + pair_block(row.text_a, row.text_b) + "\n" + TAIL)


# ---------------- cached, retrying calls ----------------
lock = threading.Lock()
cache = {}
if CACHE.exists():
    for line in CACHE.read_text(encoding="utf-8").splitlines():
        rec = json.loads(line)
        cache[(rec["pair_id"], rec["variant"])] = rec
_next_slot = [0.0]
stats = {"calls": 0, "attempts": 0, "in": 0, "out": 0, "failed": 0}


def call(row, variant):
    key = (row.pair_id, variant)
    if key in cache:
        return
    prompt = make_prompt(row, variant)
    for attempt in range(MAX_ATTEMPTS):
        with lock:                                       # global rate limiter: one request start per MIN_INTERVAL
            stats["attempts"] += 1
            wait = max(0.0, _next_slot[0] - time.time())
            _next_slot[0] = max(_next_slot[0], time.time()) + MIN_INTERVAL
        time.sleep(wait)
        try:
            resp, usage = client.generate_json_usage(prompt)
            assert isinstance(resp.get("same_intended_line"), bool), "bad schema"
            rec = {"pair_id": row.pair_id, "variant": variant, "response": resp, "usage": usage}
            with lock:
                cache[key] = rec
                with open(CACHE, "a", encoding="utf-8") as f:
                    f.write(json.dumps(rec) + "\n")
                stats["calls"] += 1
                stats["in"] += usage["in"]; stats["out"] += usage["out"]
            return
        except Exception as e:                                   # rate limits, 5xx, bad JSON -> backoff and retry
            last = scrub(e)
            if "PerDay" in last or "per day" in last.lower() or "limit: 20" in last:
                print("Daily quota exhausted; stopping. Rerun later (cache is kept).")
                os._exit(2)
            time.sleep(min(60, 2 ** attempt * 2))
    with lock:
        stats["failed"] += 1
    print(f"FAILED {row.pair_id} {variant}: {last[:150]}")


def run(rows, variant):
    todo = [r for r in rows.itertuples() if (r.pair_id, variant) not in cache]
    print(f"[{variant}] {len(rows)} pairs, {len(todo)} to call, {len(rows) - len(todo)} cached")
    t0 = time.time()
    with ThreadPoolExecutor(WORKERS) as ex:
        list(ex.map(lambda r: call(r, variant), todo))
    print(f"[{variant}] done in {time.time() - t0:.0f}s; calls so far this run {stats['calls']}, failed {stats['failed']}")


stages = sys.argv[1:] or ["zero", "few", "extra"]
band = df[df.in_band]
if "zero" in stages:
    run(band, ZERO)
if "few" in stages:
    run(band, FEW)
if "extra" in stages:
    run(errors[~errors.in_band], ZERO)                          # zero-shot on the out-of-band Stage 2 errors

# ---------------- decisions ----------------
def gem(variant):
    return df.pair_id.map(lambda p: cache[(p, variant)]["response"]["same_intended_line"] if (p, variant) in cache else np.nan)


df["llm_zero"], df["llm_few"] = gem(ZERO), gem(FEW)
# cross-encoder: per held-out fold, threshold maximising F1 on the band pairs of the OTHER folds
df["ce_decision"] = 0
df["ce_threshold"] = np.nan
for k in sorted(df.fold.unique()):
    tr = df[(df.fold != k) & df.in_band]
    prec, rec, thr = precision_recall_curve(tr.label, tr.ce_prob)
    f1 = 2 * prec[:-1] * rec[:-1] / np.clip(prec[:-1] + rec[:-1], 1e-12, None)
    t = float(thr[np.argmax(f1)])
    m = df.fold == k
    df.loc[m, "ce_decision"] = (df.loc[m, "ce_prob"] >= t).astype(int)
    df.loc[m, "ce_threshold"] = t


def prf(y, p):
    tp = int(((p == 1) & (y == 1)).sum()); fp = int(((p == 1) & (y == 0)).sum())
    fn = int(((p == 0) & (y == 1)).sum()); tn = int(((p == 0) & (y == 0)).sum())
    pr = tp / (tp + fp) if tp + fp else 0.0
    rc = tp / (tp + fn) if tp + fn else 0.0
    return {"precision": pr, "recall": rc, "F1": 2 * pr * rc / (pr + rc) if pr + rc else 0.0,
            "accuracy": (tp + tn) / max(len(y), 1), "TP": tp, "FP": fp, "FN": fn, "TN": tn}


systems = {"stage2": "s2_pred", "cross_encoder": "ce_decision"}
if band.shape[0] and df.loc[df.in_band, "llm_zero"].notna().all():
    systems["llm_zero"] = "llm_zero"
if df.loc[df.in_band, "llm_few"].notna().all() and df.in_band.any() and FEW in {v for _, v in cache}:
    systems["llm_few"] = "llm_few"
B = df[df.in_band]
scopes = [("pooled", B)] + [(f"fold{k}", B[B.fold == k]) for k in sorted(B.fold.unique())]
dec = lambda g, s: g[systems[s]].astype(int).values

md = ["# Adjudication on the ambiguous band", "",
      f"Band = Stage 2 score in [{LO}, {HI}): {len(B)} pairs, {int(B.label.sum())} positives. Outside the band Stage 2 decides "
      f"(>= {S2_T} retake, < {LO} not retake). Model {ADJUDICATION_MODEL}, temperature 0, prompt variants {ZERO} / {FEW} "
      "(fixed before scoring). Cross-encoder threshold per held-out fold chosen on the other folds' band pairs (max F1). "
      "Stage 2 on band pairs is 'decision at 0.65', i.e. always negative inside the band by construction.", ""]
md += ["### Band pairs only", "", "| system | scope | precision | recall | F1 | accuracy | TP | FP | FN | TN |", "|---|---|---|---|---|---|---|---|---|---|"]
for s in systems:
    for sc, g in scopes:
        r = prf(g.label.values, dec(g, s))
        md.append(f"| {s} | {sc} | {r['precision']:.3f} | {r['recall']:.3f} | {r['F1']:.3f} | {r['accuracy']:.3f} | "
                  f"{r['TP']} | {r['FP']} | {r['FN']} | {r['TN']} |")
md.append("")

# end to end: band decisions merged with Stage 2's decisions outside the band
y_all = df.label.values
e2e = {s: np.where(df.in_band, df[systems[s]].fillna(0).astype(int), df.s2_pred).astype(int) for s in systems}
md += [f"### End to end (all {len(df)} real rows; outside the band = Stage 2 decision)", "",
       "| system | precision | recall | F1 | TP | FP | FN |", "|---|---|---|---|---|---|---|"]
for s in systems:
    r = prf(y_all, e2e[s])
    md.append(f"| {s} | {r['precision']:.3f} | {r['recall']:.3f} | {r['F1']:.3f} | {r['TP']} | {r['FP']} | {r['FN']} |")
md.append("")

# paired video-level bootstrap of the F1 difference vs Stage 2 alone
rng = np.random.default_rng(SEED)
vids = df.video_id.unique()
idx_by_vid = {v: np.where(df.video_id.values == v)[0] for v in vids}
f1s = {s: [] for s in systems}
for _ in range(N_BOOT):
    idx = np.concatenate([idx_by_vid[v] for v in rng.choice(vids, len(vids), replace=True)])
    for s in systems:
        f1s[s].append(prf(y_all[idx], e2e[s][idx])["F1"])
md += ["### Paired video-level bootstrap: end-to-end F1 minus Stage 2 alone (1000 resamples, seed 0)", "",
       "| system | diff | 95% CI | CI excludes 0 |", "|---|---|---|---|"]
for s in systems:
    if s == "stage2":
        continue
    d = np.array(f1s[s]) - np.array(f1s["stage2"])
    lo, hi = np.percentile(d, [2.5, 97.5])
    pt = prf(y_all, e2e[s])["F1"] - prf(y_all, e2e["stage2"])["F1"]
    md.append(f"| {s} | {pt:+.3f} | [{lo:+.3f}, {hi:+.3f}] | {lo > 0 or hi < 0} |")
md.append("")

# agreement between Gemini and the cross-encoder on band pairs
md += ["### Agreement of the LLM with the cross-encoder (band pairs)", "",
       "| llm variant | agree | accuracy when agree | accuracy when disagree | LLM acc on disagreements | CE acc on disagreements |",
       "|---|---|---|---|---|---|"]
for s in [x for x in systems if x.startswith("llm")]:
    g, c, yy = B[s].astype(int).values, B.ce_decision.values, B.label.values
    ag = g == c
    acc = lambda m, p: float((p[m] == yy[m]).mean()) if m.any() else float("nan")
    md.append(f"| {s} | {ag.mean():.1%} ({int(ag.sum())}/{len(B)}) | {acc(ag, g):.3f} | "
              f"{(float((g[~ag] == yy[~ag]).mean() + (c[~ag] == yy[~ag]).mean()) / 2) if (~ag).any() else float('nan'):.3f} | "
              f"{acc(~ag, g):.3f} | {acc(~ag, c):.3f} |")
md.append("")

# Stage 2 errors: inside / outside the band and what each system does with them
fn_all, fp_all = errors[errors.label == 1], errors[errors.label == 0]
md += [f"### The {len(errors)} Stage 2 errors", "",
       f"- FN: {len(fn_all)} total, {int(fn_all.in_band.sum())} inside the band, {int((~fn_all.in_band).sum())} outside "
       f"(below {LO}).",
       f"- FP: {len(fp_all)} total, {int(fp_all.in_band.sum())} inside the band. FPs have Stage 2 score >= {S2_T}, "
       "so they can never fall in a band that ends at 0.65 and the band systems cannot fix them.", ""]
rows = []
for r in df[(df.s2_pred != df.label) | df.in_band].itertuples():
    status = "stage2_error" if r.s2_pred != r.label else "band_correct"
    rec = {"pair_id": r.pair_id, "video_id": r.video_id, "fold": r.fold, "label": r.label, "stage2": r.current_stage2,
           "stage2_error": "FN" if (r.s2_pred == 0 and r.label == 1) else ("FP" if r.s2_pred == 1 and r.label == 0 else ""),
           "in_band": bool(r.in_band), "text_a": r.text_a, "text_b": r.text_b, "ce_prob": r.ce_prob,
           "ce_decision": r.ce_decision, "llm_zero": r.llm_zero, "llm_few": r.llm_few}
    rows.append(rec)
err = pd.DataFrame(rows)
tab = ["| system | FN in band fixed | FN in band still missed | new FP in band (breaks) |", "|---|---|---|---|"]
for s in [x for x in systems if x != "stage2"]:
    inb = err[err.in_band]
    fixed = int(((inb.label == 1) & (inb[{"cross_encoder": "ce_decision"}.get(s, s)].astype(float) == 1)).sum())
    missed = int(((inb.label == 1)).sum()) - fixed
    newfp = int(((inb.label == 0) & (inb[{"cross_encoder": "ce_decision"}.get(s, s)].astype(float) == 1)).sum())
    tab.append(f"| {s} | {fixed} | {missed} | {newfp} |")
md += tab + [""]
# status column per system for the CSV
for s in [x for x in systems if x != "stage2"]:
    col = {"cross_encoder": "ce_decision"}.get(s, s)
    err[f"{s}_outcome"] = np.select(
        [err.in_band & (err.label == 1) & (err[col].astype(float) == 1), err.in_band & (err.label == 1),
         err.in_band & (err.label == 0) & (err[col].astype(float) == 1)],
        ["fixed_FN", "still_FN", "new_FP"], default="")
err.sort_values(["stage2_error", "fold"], ascending=[False, True]).to_csv(OUT / f"adjudication_errors{SUFFIX}.csv", index=False)

# extra analysis (separate): zero-shot on all Stage 2 errors regardless of band
ex_rows = df.loc[errors.index][[(p, ZERO) in cache for p in errors.pair_id]]   # from df: has the llm_* columns
if len(ex_rows) == len(errors):
    g = ex_rows.llm_zero.astype(int)
    fixed = int(((ex_rows.label == 1) & (g == 1)).sum()) + int(((ex_rows.label == 0) & (g == 0)).sum())
    md += [f"### Extra analysis (separate): zero-shot on all {len(errors)} Stage 2 errors regardless of band", "",
           f"- LLM zero-shot corrects {fixed} of {len(ex_rows)} (FN: {int(((ex_rows.label == 1) & (g == 1)).sum())} of "
           f"{len(fn_all)}; FP: {int(((ex_rows.label == 0) & (g == 0)).sum())} of {len(fp_all)}).",
           "- This is a selected sample of errors only (no correct Stage 2 pairs), so it measures recoverability, not net accuracy.", ""]

# usage / cost: sum over every cached response (including earlier runs)
tin = sum(r["usage"]["in"] for r in cache.values()); tout = sum(r["usage"]["out"] for r in cache.values())
cost = tin / 1e6 * PRICE_IN + tout / 1e6 * PRICE_OUT
md += ["### API usage", "",
       f"- Cached successful responses (all runs): {len(cache)}; this run: {stats['calls']} calls, {stats['attempts']} attempts, "
       f"{stats['failed']} failed.", f"- Tokens (all cached): {tin:,} input, {tout:,} output (incl. thinking).",
       f"- Cost at ${PRICE_IN}/M in and ${PRICE_OUT}/M out: ${cost:.3f}.", ""]

# 3-line summary
best = max([s for s in systems if s != "stage2"], key=lambda s: prf(y_all, e2e[s])["F1"])
md += ["## Summary", "",
       "1. Band pairs: " + "; ".join(f"{s} F1 {prf(B.label.values, dec(B, s))['F1']:.3f}" for s in systems) + ".",
       f"2. End to end F1: " + "; ".join(f"{s} {prf(y_all, e2e[s])['F1']:.3f}" for s in systems) + f" (best: {best}).",
       f"3. Inside the band: {int(fn_all.in_band.sum())} of {len(fn_all)} FN, {int(fp_all.in_band.sum())} of {len(fp_all)} FP; "
       f"{len(cache)} cached LLM responses, ${cost:.2f}."]
(OUT / f"adjudication{SUFFIX}.md").write_text(insert_header(md, labels_header(HERE / "pairs_v2.csv", HERE / "folds.json", len(df), int(df.label.sum()))), encoding="utf-8")

keep = ["pair_id", "video_id", "fold", "label", "in_band", "current_stage2", "llm_zero", "llm_few", "ce_prob", "ce_decision"]
df.rename(columns={"in_band": "in_band"})[keep].rename(columns={"in_band": "band_flag"}).to_csv(
    OUT / f"adjudication_scores{SUFFIX}.csv", index=False)
print("\n".join(md))
